(() => {
  const ID = 'hoop-shot';
  const shell = () => window.TelePlayGameShell;
  const tg = window.Telegram?.WebApp;
  let screen, ball, hint, scoreEl, shots = 0, baskets = 0, streak = 0, score = 0, running = false, callbacks = {}, initialized = false, busy = false;
  const haptic = type => { try { tg?.HapticFeedback?.impactOccurred(type); } catch (_) {} };
  function shoot(zone) { if (!running || busy) return; busy = true; shots += 1; ball.classList.add('is-shot'); const perfect = zone === 'center', scored = perfect || Math.random() > .28; setTimeout(() => { ball.classList.remove('is-shot'); if (scored) { baskets += 1; streak += 1; score += perfect ? 130 + streak * 10 : 70; hint.textContent = perfect ? 'PERFECT SWISH' : 'Попадание'; haptic(perfect ? 'medium' : 'light'); } else { streak = 0; score = Math.max(0, score - 20); hint.textContent = 'Мимо — измени геометрию броска'; haptic('heavy'); } scoreEl.textContent = score; busy = false; if (shots >= 8) finish(); }, 360); }
  function finish() { if (!running) return; running = false; const previous = shell().getStats(ID), result = shell().saveResult(ID, score, { bestBaskets: Math.max(previous.bestBaskets || 0, baskets), lastResult: { score, shots, baskets, streak } }), reward = Math.max(1, Math.floor(score / 125)); window.TelePlayCore?.RewardManager?.award(ID, { coins: reward, score, metadata: { transactionId: `game:${ID}:run:${Date.now()}`, shots, baskets, perfectShots: Math.floor(score / 130) } }); shell().emit('hoop_shot_finished', { gameId: ID, score, shots, baskets, streak, reward }); shell().emit('game_finished', { gameId: ID, score, reward, shots, baskets, streak }); shell().ResultScreen.show(screen.querySelector('[data-hoop-result]'), { score, bestScore: result.bestScore, reward, newRecord: result.newRecord, title: baskets >= 5 ? 'Серия<br>собрана!' : 'Щит<br>изменён', details: { baskets: `${baskets} / ${shots}`, streak: `×${streak}` } }); screen.querySelector('[data-hoop-result]').hidden = false; }
  function start() { shots = 0; baskets = 0; streak = 0; score = 0; running = true; busy = false; screen.querySelector('[data-hoop-start]').hidden = true; screen.querySelector('[data-hoop-result]').hidden = true; scoreEl.textContent = '0'; shell().emit('hoop_shot_started', { gameId: ID }); shell().emit('game_started', { gameId: ID }); haptic('light'); }
  function open(options = {}) { callbacks = options; screen.hidden = false; screen.querySelector('[data-hoop-start]').hidden = false; screen.querySelector('[data-hoop-result]').hidden = true; const stats = shell().getStats(ID); screen.querySelector('[data-hoop-menu-best]').textContent = Number(stats.bestScore || 0).toLocaleString('ru-RU'); try { tg?.requestFullscreen?.(); tg?.disableVerticalSwipes?.(); } catch (_) {} }
  function hide() { running = false; screen.hidden = true; try { tg?.enableVerticalSwipes?.(); tg?.exitFullscreen?.(); } catch (_) {} }
  function close() { hide(); callbacks.onHome?.(); }
  function init() { if (initialized) return; initialized = true; screen = document.getElementById('hoopShotScreen'); screen.innerHTML = `<div class="hoop-shot-inner"><header class="hoop-shot-hud"><button class="icon-button" data-hoop-close aria-label="На главную">×</button><div class="hoop-shot-brand"><small>TELEPLAY · СПОРТ</small><b>Hoop Shot</b></div><div class="hoop-shot-stat"><small>СЧЁТ</small><b data-hoop-score>0</b></div><button class="icon-button" data-hoop-reset aria-label="Начать заново">↻</button></header><div class="hoop-court"><span class="hoop-backboard"></span><span class="hoop-rim"></span><span class="hoop-net"></span><span class="hoop-ball" data-hoop-ball></span></div><p class="hoop-hint" data-hoop-hint>Измени угол броска и попади в кольцо</p><div class="hoop-board-controls"><button type="button" data-hoop-left>ЛЕВЫЙ</button><button type="button" data-hoop-center>ЦЕНТР</button><button type="button" data-hoop-right>ПРАВЫЙ</button></div></div><div class="start-panel" data-hoop-start><span class="panel-kicker">TELEPLAY · СПОРТ</span><h2>Hoop<br>Shot</h2><p>Меняй геометрию среды.<br>Собери идеальную серию бросков.</p><button class="play-button large" data-hoop-start-button>Начать серию</button><div class="record">Лучший результат: <b data-hoop-menu-best>0</b></div></div><div class="start-panel result-panel" data-hoop-result hidden><span class="panel-kicker" data-result="kicker">БРОСКИ ЗАВЕРШЕНЫ</span><h2 data-result="title">Серия<br>собрана!</h2><div class="result-score"><small>РЕЗУЛЬТАТ</small><b data-result="score">0</b></div><div class="result-details"><span>Лучший результат <b data-result="best">0</b></span><span>Получено <b data-result="reward">+0 🪙</b></span><span>Попадания <b data-result="baskets">0 / 8</b></span><span>Серия <b data-result="streak">×0</b></span></div><button class="play-button large" data-hoop-replay>Новая серия</button><button class="text-button" data-hoop-home>На главную</button></div>`; ball = screen.querySelector('[data-hoop-ball]'); hint = screen.querySelector('[data-hoop-hint]'); scoreEl = screen.querySelector('[data-hoop-score]'); screen.querySelector('[data-hoop-left]').addEventListener('click', () => shoot('left')); screen.querySelector('[data-hoop-center]').addEventListener('click', () => shoot('center')); screen.querySelector('[data-hoop-right]').addEventListener('click', () => shoot('right')); screen.querySelector('[data-hoop-start-button]').addEventListener('click', start); screen.querySelector('[data-hoop-replay]').addEventListener('click', start); screen.querySelector('[data-hoop-home]').addEventListener('click', close); screen.querySelector('[data-hoop-close]').addEventListener('click', close); screen.querySelector('[data-hoop-reset]').addEventListener('click', start); }
  window.HoopShotGame = { init, open, hide, close, start, restart: start, destroy: hide };
  document.readyState === 'loading' ? document.addEventListener('DOMContentLoaded', init) : init();
})();
